CREATE COLUMN TABLE "TEST_AP"."OCIP" ("AbsEntry" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(10) NOT NULL , "Name" NVARCHAR(254), "DsplID" INTEGER CS_INT, "IsEnable" NVARCHAR(1), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
